// Turns data/events.seed.json into supabase/seed.sql so the app and the database share one source of truth.
// Run with: npm run db:seed-sql
import { readFileSync, writeFileSync } from "node:fs";

const events = JSON.parse(readFileSync(new URL("../data/events.seed.json", import.meta.url), "utf8"));

const q = (v) => (v === null || v === undefined ? "null" : `'${String(v).replaceAll("'", "''")}'`);
const arr = (a) => `array[${a.map(q).join(", ")}]::text[]`;

const lines = [
  "-- Generated by scripts/generate-seed.mjs from data/events.seed.json. Do not edit by hand.",
  "-- Source: community Ghana Race Calendar (updated 7 Nov 2026), plus organiser pages where noted.",
  "",
];

const organisers = [...new Set(events.map((e) => e.organiser).filter(Boolean))];
for (const name of organisers) {
  lines.push(`insert into public.organisers (name) values (${q(name)}) on conflict (name) do nothing;`);
}
lines.push("");

for (const e of events) {
  lines.push(
    `insert into public.events (slug, name, event_date, start_time, region, city, venue, organiser_id, fee_summary, fee_kind, currency,
  registration_method, registration_url, registration_note, highlights, walker_friendly, verification, verified_at, source_name, cover_color,
  poster_path, poster_width, poster_height, poster_alt, status)
values (${q(e.slug)}, ${q(e.name)}, ${q(e.date)}, ${q(e.startTime)}, ${q(e.region)}, ${q(e.city)}, ${q(e.venue)},
  ${e.organiser ? `(select id from public.organisers where name = ${q(e.organiser)})` : "null"},
  ${q(e.feeSummary)}, ${q(e.feeKind)}, ${q(e.currency)}, ${q(e.registration.method)}, ${q(e.registration.url)}, ${q(e.registration.note)},
  ${arr(e.highlights)}, ${e.walkerFriendly === null ? "null" : e.walkerFriendly}, ${q(e.verification)}, ${q(e.verifiedAt)},
  ${q(e.verification === "verified" ? "Organiser booking page" : "Community Ghana Race Calendar")}, ${q(e.coverColor)},
  ${q(e.poster?.src)}, ${e.poster?.width ?? "null"}, ${e.poster?.height ?? "null"}, ${q(e.poster?.alt)}, 'published')
on conflict (slug) do nothing;`,
  );
  e.distances.forEach((d, i) => {
    lines.push(
      `insert into public.event_distances (event_id, label, category, price_minor, note, sort)
select id, ${q(d.label)}, ${q(d.category)}, ${d.priceMinor ?? "null"}, ${q(d.note)}, ${i} from public.events where slug = ${q(e.slug)}
  and not exists (select 1 from public.event_distances x where x.event_id = events.id and x.label = ${q(d.label)});`,
    );
  });
  lines.push("");
}

writeFileSync(new URL("../supabase/seed.sql", import.meta.url), lines.join("\n"));
console.log(`Wrote supabase/seed.sql with ${events.length} events.`);
